import pathlib
p = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/src/codegen_support/runtime/emitters/frame_balance_tests.rs')
t = p.read_text()
t = t.replace('    Unanalysable,
}', '    Unanalysable(String),
}')
t = t.replace('    let mut unanalysable = false;
', '    let mut unanalysable: Option<String> = None;
')
t = t.replace('                    if previous != delta {
                        unanalysable = true;
                    }',
              '                    if previous != delta {
                        unanalysable = Some(format!("two depths at `{}`", helper.instructions[pc]));
                    }')
t = t.replace('                SpEffect::Opaque => {
                    unanalysable = true;
                    break;
                }',
              '                SpEffect::Opaque => {
                    unanalysable = Some(format!("opaque `{inst}`"));
                    break;
                }')
t = t.replace('                Some(None) => unanalysable = true,',
              '                Some(None) => unanalysable = Some(format!("indirect `{inst}`")),')
t = t.replace('    if unanalysable {
        Verdict::Unanalysable
    } else {
        Verdict::Balanced
    }',
              '    match unanalysable {
        Some(why) => Verdict::Unanalysable(why),
        None => Verdict::Balanced,
    }')
t = t.replace('                Verdict::Unanalysable => {
                    unanalysable_found.insert(name.clone());
                }',
              '                Verdict::Unanalysable(why) => {
                    unanalysable_found.insert(format!("{name} ({why})"));
                }')
t = t.replace('        .filter(|name| !exempt.contains_key(name.as_str()))',
              '        .filter(|name| {
            let bare = name.split(" (").next().unwrap_or(name);
            !exempt.contains_key(bare)
        })')
p.write_text(t)
print('diagnostic added')
